# Real native KeyDrive/PWM scheduler, guarded fabricated-lower consumer. No OS input.
param([string]$RepoRoot=(Split-Path $PSScriptRoot -Parent),[Parameter(Mandatory=$true)][string]$CliDir,[string]$DllDir,[string]$Out,[switch]$Baseline)
$ErrorActionPreference='Stop';$RepoRoot=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $RepoRoot).Path)
if($PSVersionTable.PSVersion.Major-lt7){throw 'PowerShell7 required for original ProcessStartInfo.ArgumentList'}
$CliDir=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $CliDir).Path);if(-not$DllDir){$DllDir=$CliDir};$DllDir=[IO.Path]::GetFullPath((Resolve-Path -LiteralPath $DllDir).Path)
if(-not$Out){$Out=Join-Path $RepoRoot 'verify/session11_keydrive/native'};$outRoot=[IO.Path]::GetFullPath($Out)
