$checks=[Collections.Generic.List[object]]::new();$arches=[Collections.Generic.List[object]]::new();$cases=[Collections.Generic.List[object]]::new();$calls=[Collections.Generic.List[object]]::new();$processes=[Collections.Generic.List[object]]::new();$pins=[Collections.Generic.List[object]]::new()
$complete=$false;$instrument=$true;$sourceStable=$false;$current=$null;$serial=0;$token=0;$problem=$null;$owner='keydrive-'+[guid]::NewGuid().ToString('N')
. "$RepoRoot/verify/vi_r1_identity.ps1"
. "$RepoRoot/verify/vi_exited_cli_accounting.ps1"
. "$RepoRoot/verify/vi_r1_lifecycle.ps1"
. "$RepoRoot/verify/_vcvars.ps1";$vcRoot=Get-VcVarsDir
if(-not('ViWndProcAwTail'-as[type])){Add-Type -Path "$RepoRoot/test/vi_r1_tail.cs"}
